DROP TABLE IF EXISTS `Player`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Player` (
  `id` int DEFAULT NULL,
  `Player` varchar(255) NOT NULL,
  `Salary` int DEFAULT NULL,
  `Year` varchar(9) NOT NULL,
  `Pos` varchar(255) DEFAULT NULL,
  `Age` int DEFAULT NULL,
  `Team` varchar(3) NOT NULL,
  `G` int DEFAULT NULL,
  `GS` int DEFAULT NULL,
  `MP` float DEFAULT NULL,
  `FG` float DEFAULT NULL,
  `FGA` float DEFAULT NULL,
  `FG_pct` float DEFAULT NULL,
  `3P` float DEFAULT NULL,
  `3PA` float DEFAULT NULL,
  `3P_pct` float DEFAULT NULL,
  `2P` float DEFAULT NULL,
  `2PA` float DEFAULT NULL,
  `2P_pct` float DEFAULT NULL,
  `eFG_pct` float DEFAULT NULL,
  `FT` float DEFAULT NULL,
  `FTA` float DEFAULT NULL,
  `FT_pct` float DEFAULT NULL,
  `ORB` float DEFAULT NULL,
  `DRB` float DEFAULT NULL,
  `TRB` float DEFAULT NULL,
  `AST` float DEFAULT NULL,
  `STL` float DEFAULT NULL,
  `BLK` float DEFAULT NULL,
  `TOV` float DEFAULT NULL,
  `PF` float DEFAULT NULL,
  `PTS` float DEFAULT NULL,
  PRIMARY KEY (`Player`,`Year`),
  KEY `FK_team_year_player` (`Year`,`Team`),
  CONSTRAINT `FK_team_year_player` FOREIGN KEY (`Year`, `Team`) REFERENCES `Teams` (`Year`, `Team`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
